<?php
require_once 'functions.php';require_login();$me=current_user();$target=(int)($_GET['user_id']??0);$admin=$me['role']==='admin';if($target&&!$admin){http_response_code(403);exit('Akses ditolak.');}
$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$uid=$admin?(int)($_POST['user_id']??0):(int)$me['id'];$pw=$_POST['new_password']??'';$confirm=$_POST['confirm_password']??'';$st=$pdo->prepare('SELECT role FROM users WHERE id=?');$st->execute([$uid]);$targetUser=$st->fetch();if(!$targetUser||($admin&&$targetUser['role']!=='member'))$error='Akun tidak ditemukan atau tidak diizinkan.';elseif(strlen($pw)<8)$error='Password minimal 8 karakter.';elseif($pw!==$confirm)$error='Konfirmasi password tidak sama.';else{$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($pw,PASSWORD_DEFAULT),$uid]);flash('Password berhasil diperbarui.');header('Location: '.($admin?'members.php':'dashboard.php'));exit;}}
$members=$admin?$pdo->query("SELECT id,full_name FROM users WHERE role='member' ORDER BY full_name")->fetchAll():[];$pageTitle='Ganti Password';$active='';require 'header.php';?>
<div class="form-card"><p class="eyebrow">KEAMANAN AKUN</p><h3><?=$admin?'Reset Password Member':'Ubah Password Saya'?></h3><p class="muted small">Password lama tidak ditampilkan demi keamanan. Admin dapat menetapkan password baru untuk member.</p><?php if($error): ?><div class="alert error"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><?php if($admin): ?><label>Pilih member</label><select name="user_id" required><option value="">Pilih member</option><?php foreach($members as $m): ?><option value="<?=$m['id']?>" <?=((int)$m['id']===$target)?'selected':''?>><?=e($m['full_name'])?></option><?php endforeach; ?></select><?php endif; ?><label>Password baru</label><input type="password" name="new_password" minlength="8" required><label>Ulangi password baru</label><input type="password" name="confirm_password" minlength="8" required><div class="form-actions"><a class="btn outline" href="<?=$admin?'members.php':'dashboard.php'?>">Batal</a><button class="btn primary">Simpan Password</button></div></form></div><?php require 'footer.php'; ?>
